<?php
require_once __DIR__.'/includes/auth.php';require_once __DIR__.'/includes/functions.php';$pdo=aep_database();$id=(int)($_GET['id']??0);$stmt=$pdo->prepare('SELECT t.*,m.matter_reference,m.subject FROM tasks t LEFT JOIN matters m ON m.id=t.matter_id WHERE t.id=?');$stmt->execute([$id]);$task=$stmt->fetch();if(!$task){http_response_code(404);exit('Task not found.');}
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['complete'])){aep_validate_csrf();$pdo->prepare('UPDATE tasks SET status=?,updated_at=CURRENT_TIMESTAMP WHERE id=?')->execute(['completed',$id]);aep_log_activity($pdo,'Tasks','Completed task: '.$task['title'],$id);header('Location:task_view.php?id='.$id);exit;}
$stmt=$pdo->prepare('SELECT * FROM activity_log WHERE entity=? AND entity_id=? ORDER BY created_at DESC LIMIT 20');$stmt->execute(['Tasks',$id]);$activity=$stmt->fetchAll();
$pageTitle='Task | AEP';$activeNav='tasks';require __DIR__.'/includes/header.php';?><div class="card" style="max-width:850px;margin:auto"><p class="muted">Tasks &gt; <?php echo aep_h($task['title']);?></p><div class="actions" style="justify-content:space-between"><div><span class="badge"><?php echo aep_h($task['status']);?></span><h1><?php echo aep_h($task['title']);?></h1></div><div class="actions"><?php if($task['status']!=='completed'):?><form method="post" style="display:inline"><?php echo aep_csrf_field();?><input type="hidden" name="complete" value="1"><button class="btn">Mark as completed</button></form><?php endif;?><a class="btn secondary" href="task_edit.php?id=<?php echo $id;?>">Edit</a><a class="btn danger" href="task_delete.php?id=<?php echo $id;?>">Delete</a></div></div><p><?php echo nl2br(aep_h($task['description']));?></p><p class="muted">Due: <?php echo aep_h($task['due_date']?:'Not set');?><?php if($task['matter_reference']):?> · Matter: <a href="matter_view.php?id=<?php echo (int)$task['matter_id'];?>"><?php echo aep_h($task['matter_reference']);?></a><?php endif;?></p>
<?php if($activity):?><h2>Activity</h2><ul><?php foreach($activity as $entry):?><li><span class="muted"><?php echo aep_h($entry['created_at']);?></span> — <?php echo aep_h($entry['action']);?></li><?php endforeach;?></ul><?php endif;?>
</div><?php require __DIR__.'/includes/footer.php';?>
